-- =========================================
-- Captures of the official formats (development data)
-- =========================================
-- Eight captures of the 2024-2025 formats, one per responsible area: six submitted and two
-- still drafts. They were produced through the API, so the template engine validated every
-- submission — the sums add up and no required answer is missing. Where the system already
-- computes a figure (aprovechamiento, deserción, eficiencia terminal), the capture reports
-- the same one as the academic history.
--
-- Requires: migrations, test-data.sql and seed-official-catalogs.sql; to open a capture, the
-- templates shipped in UPZMG.API/ReportTemplates.
-- Run:
--   docker exec -i upzmg_db sh -c '/opt/mssql-tools18/bin/sqlcmd -S localhost -U dev_user -P "$MSSQL_DEV_PASSWORD" -C -d upzmg -b -I' < seed-report-captures.sql
--
-- Idempotent: it removes its own rows, and any capture of these formats left by the test users.

SET NOCOUNT ON;
SET XACT_ABORT ON;

BEGIN TRY
BEGIN TRANSACTION;

DECLARE @Now DATETIME2 = GETUTCDATE();
DECLARE @Answers NVARCHAR(MAX);
DECLARE @SIIAlumnosBy UNIQUEIDENTIFIER = (SELECT TOP 1 Id FROM systemUser WHERE Email = N'control.escolar@upzmg.local');
IF @SIIAlumnosBy IS NULL THROW 51000, 'Missing the test users. Run test-data.sql first.', 1;
DECLARE @Carrera9ABy UNIQUEIDENTIFIER = (SELECT TOP 1 Id FROM systemUser WHERE Email = N'control.escolar@upzmg.local');
IF @Carrera9ABy IS NULL THROW 51000, 'Missing the test users. Run test-data.sql first.', 1;
DECLARE @Escuela9By UNIQUEIDENTIFIER = (SELECT TOP 1 Id FROM systemUser WHERE Email = N'admin@upzmg.local');
IF @Escuela9By IS NULL THROW 51000, 'Missing the test users. Run test-data.sql first.', 1;
DECLARE @Institucion10By UNIQUEIDENTIFIER = (SELECT TOP 1 Id FROM systemUser WHERE Email = N'admin@upzmg.local');
IF @Institucion10By IS NULL THROW 51000, 'Missing the test users. Run test-data.sql first.', 1;
DECLARE @SIIDocentesBy UNIQUEIDENTIFIER = (SELECT TOP 1 Id FROM systemUser WHERE Email = N'recursos.humanos@upzmg.local');
IF @SIIDocentesBy IS NULL THROW 51000, 'Missing the test users. Run test-data.sql first.', 1;
DECLARE @SIICuerposAcademicosBy UNIQUEIDENTIFIER = (SELECT TOP 1 Id FROM systemUser WHERE Email = N'docente_01@upzmg.local');
IF @SIICuerposAcademicosBy IS NULL THROW 51000, 'Missing the test users. Run test-data.sql first.', 1;
DECLARE @SIIInfraestructuraBy UNIQUEIDENTIFIER = (SELECT TOP 1 Id FROM systemUser WHERE Email = N'recursos.materiales@upzmg.local');
IF @SIIInfraestructuraBy IS NULL THROW 51000, 'Missing the test users. Run test-data.sql first.', 1;
DECLARE @AnexoTIBy UNIQUEIDENTIFIER = (SELECT TOP 1 Id FROM systemUser WHERE Email = N'recursos.materiales@upzmg.local');
IF @AnexoTIBy IS NULL THROW 51000, 'Missing the test users. Run test-data.sql first.', 1;

-- Its own rows, plus any capture of these formats the test users may have left behind.
DELETE FROM reports
WHERE Id IN ('cccccccc-0000-0000-0000-000000000001', 'cccccccc-0000-0000-0000-000000000002', 'cccccccc-0000-0000-0000-000000000003', 'cccccccc-0000-0000-0000-000000000004', 'cccccccc-0000-0000-0000-000000000005', 'cccccccc-0000-0000-0000-000000000006', 'cccccccc-0000-0000-0000-000000000007', 'cccccccc-0000-0000-0000-000000000008')
   OR (TemplateVersion = N'2024-2025'
       AND ReportType IN (N'SII_Alumnos', N'Carrera911_9A', N'Escuela911_9', N'Institucion911_10', N'SII_Docentes', N'SII_CuerposAcademicos', N'SII_Infraestructura', N'AnexoTI')
       AND CreatedBy IN (SELECT Id FROM systemUser WHERE Email IN (N'admin@upzmg.local', N'control.escolar@upzmg.local', N'docente_01@upzmg.local', N'recursos.humanos@upzmg.local', N'recursos.materiales@upzmg.local')));

